import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import Logo from "../components/logo";

const userData: UserProfile = data;

const AboutPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="Tofu"
      footerLogoFill="fill-DeepSea"
      footerColorText="text-DeepSea"
      bgImage={images.bgAbout.src}
      paddingBottomClassBackground="pb-[100%]"
      bgColorPage="Kayaking"
      >
      <section className={styles.container}>

        <section className="w-full flex justify-end my-12 sm:my-5">
            {/* image for desktop */}
            <div className="hidden sm:flex w-1/2">
                <img 
                    src={images.icons_desktop.src} 
                    alt={images.icons_desktop.alt} 
                    className="self-end" 
                />
            </div>
            
            {/* image for mobile */}
            <div className="flex sm:hidden w-full">
                <img 
                    src={images.icons_mobile.src} 
                    alt={images.icons_mobile.alt} 
                    className="w-3/4 mx-auto" 
                />
            </div>
        </section>

        <section className="flex flex-col sm:flex-row my-5 ">
            <div className=" w-full sm:w-1/2">
                <Logo className="fill-Tofu w-[98px] sm:w-[154px] h-[32px] sm:h-[50px]" />
            </div>
            <div className=" w-full sm:w-1/2 pt-10 sm:pt-0">
                <p className="body-3 sm:body-2 ">{t("about.reef.paragraph1")}</p>
                <p className="body-3 sm:body-2 pt-10">{t("about.reef.paragraph2")}</p>
            </div>
        </section>

        <section className="flex flex-col sm:flex-row my-10">
            <div className="w-full sm:w-1/2 ">
                <h4 className="head-4 uppercase">{t("about.our_mission.title")}</h4>
            </div>
            <div className="w-full sm:w-1/2 pt-4 sm:pt-0">
                <p className="body-3 sm:body-2">{t("about.our_mission.paragraph1")}</p>
            </div>
        </section>

        <section className="flex flex-col sm:flex-row my-10">
            <div className="w-full sm:w-1/2 ">
                <h4 className="head-4 uppercase">{t("about.our_story.title")}</h4>
            </div>
            <div className="w-full sm:w-1/2 pt-4 sm:pt-0">
                <p className="body-3 sm:body-2">{t("about.our_story.paragraph1")}</p>
            </div>
        </section>

        <section className="flex flex-col sm:flex-row my-10">
            {(() => {
                const promises = t("about.our_promise", { returnObjects: true }) as any[];
                return (
                <>
                    <div className="w-full sm:w-1/2">
                        <h4  className="head-4 uppercase">{promises[0]}</h4>
                    </div>

                    <div className="w-full sm:w-1/2 pt-8 sm:pt-[1rem]">
                    {promises.slice(1).map((item, index) => (
                        <div key={index} className="flex flex-col items-start mb-10">
                            <h4 className="head-7 sm:head-5">{item.title}</h4>
                            <p className="body-4 sm:body-2 pt-0 sm:pt-5">{item.paragraph1}</p>
                        </div>
                    ))}
                    </div>
                </>
                );
            })()}
        </section>
      </section>
    </Layout>
  )
}

export default AboutPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16 text-Tofu mb-32",
  section: "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "head-3 sm:head-1 text-Tofu",
}
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={userData}
    title={translations.seo.about.title}
    description={translations.seo.about.description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    schemaType="ProfessionalService"
    pageSchemaType="AboutPage"
    pageSchemaName="About Reef Cleaning Company"
  />
);
